"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[42454],{21838:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"JunkController","desc":"Manages all client-side visuals for floating junk. Pooled model instances\\nare spawned and moved each `PreSimulation` step at a shared speed that\\nramps smoothly via smoothstep whenever the server sends a `SetJunkSpeed`\\npacket. When a claim succeeds the junk is removed from simulation and\\ntracked as retracting \u2014 other players see it slide toward the collector,\\nwhile the collecting player\'s animation is driven by `GrabHook`\'s\\n`AnimateProjectile`. `JunkCollected` returns the model to its pool.\\nAll junk-related network calls (`ReqJunkClaim`, `ReqJunkFinalize`) are\\nowned here and triggered via `Signals.TryClaimJunk` / `TryFinalizeJunk`.","realm":["Client"],"source":{"line":18,"path":"src/StarterPlayer/StarterPlayerScripts/JunkController.client.luau"}}')}}]);